def tr(i, es, en, ev, orig, ancla, crit, brecha, cond, nivel, dec):
    l, ins, cul, rec = crit
    return {"id": f"TR-{i:03d}", "practica_es": es, "practica_en": en, "evidence_ids": ev,
            "jurisdiccion_origen": orig, "ancla_cr": ancla,
            "criterios": {"legal": l, "institucional": ins, "cultural": cul, "recursos": rec},
            "brecha": brecha, "condicion_adaptacion": cond, "nivel": nivel, "decision": dec,
            "revisor": REV, "fecha": F}

