def tip(n, es, en, pq, pq_en, tema, edad, ev, trid, conf, ancla, cond=None, esf="bajo", urg="media", ctx=("casa",), adv=None):
    return {"id": f"T-FAM-{n:03d}", "texto_es": es, "texto_en": en, "por_que_es": pq, "por_que_en": pq_en,
            "tema": tema, "edad": list(edad), "publico": ["Familia"], "contexto": list(ctx),
            "esfuerzo": esf, "urgencia": urg, "confianza": conf, "evidence_ids": ev, "transfer_id": trid,
            "ancla_cr": ancla, "condicion_adaptacion": cond, "advertencia_edad": adv, "estado": "borrador",
            "revisado_por": [{"rol": "redaccion_ciodd", "fecha": F}], "fecha": F, "fecha_verificacion": F}
